"""Render shared components into three static Vite HTML entrypoints."""
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]

def header(current=''):
 return f'''<a class="skip" href="#main">Skip to content</a>
<header class="site-header wrap">
 <a class="identity" href="/" aria-label="SRM design study home"><strong>srm<span>ist</span></strong><span>Institute of Science<br>and Technology</span></a>
 <nav aria-label="Primary"><a href="/academics.html" {'aria-current="page"' if current=='academics' else ''}>Academics</a><a href="/#ways-in">Admissions</a><a href="/#research">Research</a><a href="/#campus-life">Campus life</a><a href="/#milestones">About</a></nav>
 <a class="menu-button" href="/menu.html" aria-label="Open full menu"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 8h16M4 16h16" stroke="currentColor" stroke-width="2"/></svg></a>
</header>'''

def skyline():
 windows=''.join(f'<rect x="{x}" y="{y}" width="12" height="16"/>' for x in range(216,649,32) for y in range(184,418,32))
 windows+=''.join(f'<rect x="{x}" y="{y}" width="12" height="12"/>' for x in range(828,1150,24) for y in range(106,406,24))
 return f'''<div class="skyline-note wrap"><span>TP + TP2 / skyline study</span><span>TODO: refine against real TP/TP2 photos</span></div>
<svg class="skyline" viewBox="0 0 1440 480" role="img" aria-labelledby="skyline-title skyline-desc">
<title id="skyline-title">Conceptual Tech Park and Tech Park 2 skyline</title><desc id="skyline-desc">Two simplified tower studies surrounded by trees. Placeholder architecture awaiting official exterior references.</desc>
<g id="sky"><path fill="var(--surface)" d="M0 0h1440v480H0z"/><circle cx="1260" cy="112" r="48" fill="var(--paper)"/></g>
<g id="buildings" fill="var(--line)"><path d="M176 160h512v288H176z"/><path d="M176 160l40-24h496l-24 24z" fill="var(--paper)"/><path d="M688 160l24-24v312h-24z" fill="var(--muted)"/>
<path d="M792 80h384v368H792z"/><path d="M792 80l24-24h384l-24 24z" fill="var(--paper)"/><path d="M1176 80l24-24v392h-24z" fill="var(--muted)"/>
<path d="M168 232h528v8H168zm0 64h528v8H168zm0 64h528v8H168z" fill="var(--paper)"/>
<path d="M968 80h24v368h-24z" fill="var(--paper)"/><path d="M392 160h32v288h-32z" fill="var(--paper)"/>
<path d="M360 408h112v40H360zm560 0h128v40H920z" fill="var(--accent)"/></g>
<g id="windows" fill="var(--muted)">{windows}</g>
<g id="foreground"><path d="M0 448h1440v32H0z" fill="var(--ink)"/>
{''.join(f'<path d="M{x} 368v80" stroke="var(--ink)" stroke-width="8"/><ellipse cx="{x}" cy="344" rx="40" ry="56" fill="var(--muted)"/>' for x in [64,136,744,1256,1352])}
<path d="M0 472h1440" stroke="var(--surface)" stroke-width="2"/></g></svg>'''

def footer():
 return f'''<footer class="site-footer" id="contact"><div class="wrap footer-top"><div class="footer-intro"><a class="footer-wordmark" href="/">srmist</a><p>A place to find your field.<br>And the people to go further with.</p><address>Kattankulathur, Tamil Nadu, India</address><a href="https://www.srmist.edu.in/" target="_blank" rel="noopener noreferrer">Official SRM website ↗</a></div>
<div class="footer-links"><details open><summary>Study at SRM</summary><a href="/academics.html">Explore programs</a><a href="https://www.srmist.edu.in/admission-india/" target="_blank" rel="noopener noreferrer">Apply ↗</a><a href="https://www.srmist.edu.in/contact-us/" target="_blank" rel="noopener noreferrer">Request info ↗</a></details>
<details open><summary>Explore</summary><a href="/#research">Research</a><a href="/#campus-life">Campus life</a><a href="/#work">Work from SRM</a></details>
<details open><summary>Useful links</summary><a href="https://www.srmist.edu.in/" target="_blank" rel="noopener noreferrer">Students & staff ↗</a><a href="https://www.srmist.edu.in/" target="_blank" rel="noopener noreferrer">Disclosures & policies ↗</a><a href="/menu.html">All sections</a></details></div></div>
<div class="wrap legal"><p>Independent competition design study. Not an official SRM website.</p><a href="https://www.srmist.edu.in/" target="_blank" rel="noopener noreferrer">Official notices & privacy ↗</a></div>{skyline()}</footer>'''

def figure(name,alt,caption,cls=''):
 return f'<figure class="{cls}"><img src="/assets/img/{name}-study.webp" alt="{alt}" width="1200" height="667" loading="lazy"><figcaption>{caption} / Illustration placeholder</figcaption></figure>'

hero='''<section class="hero wrap" aria-labelledby="hero-title"><div class="hero-topline"><span>Kattankulathur, Tamil Nadu</span><span>A university. A world of possibilities.</span></div>
<h1 id="hero-title"><span class="sr-only">SRM Institute of Science and Technology</span><span class="wordmark" aria-hidden="true">SRM</span></h1>
<p class="hero-credit">Campus image placeholder / Original architectural study. Official photo to follow.</p>
<div class="hero-bottom"><p class="hero-intro">Find your place in a campus<br class="desktop-break"> built for curious minds.</p><div class="hero-actions"><a class="pill primary" href="https://www.srmist.edu.in/admission-india/" target="_blank" rel="noopener noreferrer">Apply ↗</a><a class="pill" href="https://www.srmist.edu.in/contact-us/" target="_blank" rel="noopener noreferrer">Request info ↗</a><a class="pill" href="#visit">Visit campus</a></div></div>
<div class="hero-foot"><p>Engineering, science, medicine, the arts.<br>Begin with a question. Make room for what comes next.</p><a class="text-link" href="/academics.html">Explore programs</a></div></section>'''

def band(id,theme,title,copy,link,href,fact):
 return f'''<section class="statement {theme}" id="{id}" aria-labelledby="{id}-title"><img class="band-image" src="/assets/img/{theme}-study.webp" alt="" width="1200" height="667" loading="lazy"><div class="band-content wrap"><h2 id="{id}-title">{title}</h2><div class="band-detail"><p>{copy}</p><a class="pill light" href="{href}">{link}</a></div><p class="band-fact">{fact} <span>TODO: verify</span></p></div><p class="band-credit wrap">Original {theme} study / Illustration placeholder; not an SRM photograph</p></section>'''

bands=band('learn','learn','Make room<br>for discovery.','Find a field that holds your attention. Then follow it beyond the classroom.','Explore academics','/academics.html','Learning at Kattankulathur / Programme information pending review.')+band('research','research','Ask a<br>better question.','A problem worth solving can bring an engineer, a scientist and a designer to the same table.','Explore research','#work','Research at SRM / Current research figures pending review.')+band('campus-life','life','A life beyond<br>the lecture.','A conversation on the way to class. A team to join. A corner of campus that becomes yours.','Plan a visit','#visit','Campus life / Current clubs and facilities pending review.')

ways='''<section class="section wrap" id="ways-in"><div class="section-heading"><h2>Your next step.</h2><p>Three ways to get to know SRM.<br>Start wherever you are.</p></div><ol class="ways"><li><span class="step">01</span><div><h3>Make it official.</h3><p>Ready to begin? Check the current admissions cycle and entry requirements on the official site.</p><a class="text-link" href="https://www.srmist.edu.in/admission-india/" target="_blank" rel="noopener noreferrer">Apply ↗</a></div></li><li><span class="step">02</span><div><h3>Find your field.</h3><p>Explore areas of study, compare your interests and make a shortlist of questions.</p><a class="text-link" href="/academics.html">Explore programs</a></div></li><li id="visit"><span class="step">03</span><div><h3>Picture yourself here.</h3><p>Ask the campus team about visiting Kattankulathur and what you can see while you’re here.</p><a class="text-link" href="https://www.srmist.edu.in/contact-us/" target="_blank" rel="noopener noreferrer">Ask about a visit ↗</a></div></li></ol></section>'''

work='<section class="section work" id="work"><div class="wrap"><div class="section-heading"><h2>Work from SRM.</h2><p>A closer look at people and process.<br>Editorial slots awaiting verified SRM stories.</p></div><div class="work-grid">'
for name,title,copy in [('research','From question to experiment','Research story slot. Verified project, contributors and date to follow.'),('work','Thinking through making','Student work slot. Verified work, discipline and credits to follow.'),('studio','Different fields. Shared ideas.','Collaboration story slot. Verified team and outcome to follow.')]:
 work+=f'<article>{figure(name,"Illustrated worktable; placeholder for official SRM project photography","Original project illustration")}<p class="content-status">Story placeholder</p><h3>{title}</h3><p>{copy}</p></article>'
work+='</div></div></section>'

milestones='''<section class="section wrap milestones" id="milestones"><div><h2>A place that<br>keeps becoming.</h2><p class="section-copy">The story of a university is written by the people who pass through it.</p><ol class="timeline"><li><span class="year">1985</span><div><h3>A beginning in engineering.</h3><p>Founding milestone. <span class="verify">TODO: verify date and institutional history.</span></p></div></li><li><span class="year">2002</span><div><h3>A wider academic horizon.</h3><p>University-status milestone. <span class="verify">TODO: verify date and legal designation.</span></p></div></li><li><span class="year">Today</span><div><h3>The next chapter is open.</h3><p>Current institutional facts and accreditation: <span class="verify">TODO: verify.</span></p></div></li></ol></div><blockquote><p>“What you learn here is only the beginning of what you can do with it.”</p><footer>Original editorial statement for this design study.<br>Not an attributed testimonial.</footer></blockquote></section>'''
partners='''<section class="partners wrap" aria-labelledby="partners-title"><div class="section-heading"><h2 id="partners-title">Ideas travel further together.</h2><p>Partner wall / Placeholder.<br>Names and permissions awaiting verification.</p></div><div class="partner-wall" aria-label="Unfilled partner logo slots"><span>Research partner<br><small>Logo pending</small></span><span>Industry partner<br><small>Logo pending</small></span><span>Academic partner<br><small>Logo pending</small></span><span>Community partner<br><small>Logo pending</small></span></div></section>'''

academics='''<section class="page-intro wrap"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span>Academics</span></nav><h1>Follow your<br>curiosity.</h1><div class="section-heading"><p class="serif-lead">A technical question.<br>A creative impulse.<br>A field you haven’t met yet.</p><div><p>Explore the spaces where your interests might take shape. This is a static template for an academics landing page.</p><a class="pill primary" href="https://www.srmist.edu.in/" target="_blank" rel="noopener noreferrer">View official programs ↗</a></div></div></section>'''+figure('learn','Architectural illustration standing in for an official SRM teaching-building photo','Original architectural study','wide-figure')+'''<section class="section wrap"><div class="section-heading"><h2>Find a starting point.</h2><p>Illustrative study areas, not a verified catalogue.<br>Confirm programme titles and availability with SRM.</p></div><div class="study-list">'''+''.join(f'<div><h3>{title}</h3><p>{copy}</p><a href="https://www.srmist.edu.in/" target="_blank" rel="noopener noreferrer">Official course information ↗</a></div>' for title,copy in [('Engineering & technology','Work from how things behave to how they could work better.'),('Science & research','Observe closely. Ask why. Put an idea to the test.'),('Medicine & health','Explore the study of people, care and human health.'),('Arts & humanities','Look at the world through language, culture and creative practice.')])+'''</div></section><section class="contact-band"><div class="wrap"><h2>You don’t need all<br>the answers yet.</h2><p>Bring your questions about courses, entry requirements and campus life to the admissions team.</p><a class="pill primary" href="https://www.srmist.edu.in/contact-us/" target="_blank" rel="noopener noreferrer">Request info ↗</a></div></section>'''
menu='''<section class="page-intro wrap menu-page"><div class="menu-heading"><h1>Find your way.</h1><a class="pill" href="/">Back to home</a></div><nav class="full-menu" aria-label="All sections">'''+''.join(f'<a href="{url}"><span>{title}</span><span class="menu-description">{desc}</span></a>' for title,url,desc in [('Academics','/academics.html','Find your field'),('Admissions','/#ways-in','Take your next step'),('Research','/#research','Questions worth asking'),('Campus life','/#campus-life','See yourself here'),('About SRM','/#milestones','A university in the making'),('Contact','/#contact','Start a conversation')])+'''</nav><p class="study-notice">Static competition design study. Use the <a href="https://www.srmist.edu.in/" target="_blank" rel="noopener noreferrer">official SRM website ↗</a> for current institutional information.</p></section>'''

for filename,title,content,current in [('index.html','SRM IST — Find your field',hero+bands+ways+work+milestones+partners,''),('academics.html','Academics — SRM IST design study',academics,'academics'),('menu.html','Menu — SRM IST design study',menu,'')]:
 (ROOT/filename).write_text(f'''<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="An independent static design study for SRM Institute of Science and Technology, Kattankulathur. Explore academics and campus life."><meta name="theme-color" content="#f5f7f7"><title>{title}</title><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/styles/site.css"></head><body>{header(current)}<main id="main">{content}</main>{footer()}</body></html>''')
